      "index.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Exercício 04 — Capturando Nome com Input</title>\n    <link rel=\"stylesheet\" href=\"estilo.css\">\n    <script src=\"script.js\" defer></script>\n</head>\n<body>\n    <main class=\"container\">\n        <h1>Capturando Nome com Input</h1>\n        <label for=\"nome\">Nome do aluno:</label>\n        <input type=\"text\" id=\"nome\" placeholder=\"Digite seu nome\">\n        <button id=\"mostrarNome\" type=\"button\">Mostrar saudação</button>\n        <p id=\"mensagem\" class=\"resultado\">A saudação aparecerá aqui.</p>\n    </main>\n</body>\n</html>\n",
      "estilo.css": "* {\n    box-sizing: border-box;\n}\n\nbody {\n    margin: 0;\n    min-height: 100vh;\n    padding: 40px 16px;\n    font-family: Arial, sans-serif;\n    background-color: #f3f4f6;\n    color: #1f2937;\n}\n\n.container {\n    width: min(620px, 100%);\n    margin: auto;\n    padding: 28px;\n    background-color: white;\n    border-radius: 14px;\n    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.10);\n}\n\nh1 {\n    margin-top: 0;\n    color: #0369a1;\n}\n\np {\n    line-height: 1.5;\n}\n\nlabel {\n    display: block;\n    margin-top: 16px;\n    font-weight: bold;\n}\n\ninput, textarea, select, button {\n    font: inherit;\n}\n\ninput, textarea, select {\n    width: 100%;\n    margin-top: 7px;\n    padding: 11px;\n    border: 1px solid #cbd5e1;\n    border-radius: 8px;\n}\n\nbutton {\n    margin-top: 18px;\n    padding: 10px 16px;\n    border: 0;\n    border-radius: 8px;\n    background-color: #0369a1;\n    color: white;\n    cursor: pointer;\n}\n\nbutton:hover {\n    filter: brightness(0.9);\n}\n\n.resultado {\n    min-height: 28px;\n    margin-top: 20px;\n    padding: 14px;\n    border-left: 4px solid #0369a1;\n    background-color: #f0f9ff;\n    border-radius: 8px;\n}\n\nul {\n    padding-left: 22px;\n}\n\n@media (max-width: 520px) {\n    body {\n        padding: 20px 12px;\n    }\n\n    .container {\n        padding: 20px;\n    }\n}\n",
      "script.js": "const campoNome = document.querySelector(\"#nome\");\nconst botao = document.querySelector(\"#mostrarNome\");\nconst mensagem = document.querySelector(\"#mensagem\");\n\nbotao.addEventListener(\"click\", () => {\n    const nome = campoNome.value.trim();\n\n    if (nome === \"\") {\n        mensagem.textContent = \"Digite seu nome antes de continuar.\";\n        return;\n    }\n\n    mensagem.textContent = \"Bem-vindo, \" + nome + \"!\";\n});\n"
